void init_zelda_sound(void)
{
    unsigned char i;

    poke(0x0801, 0xFF);

    poke(0x0800, 0);
    poke(0x0804, 0x40);
    poke(0x0804, 0x00);
    for (i = 0; i < 32; i++) {
        poke(0x0806, zelda_square_wave[i]);
    }
    poke(0x0805, 0xFF);

    poke(0x0800, 1);
    poke(0x0804, 0x40);
    poke(0x0804, 0x00);
    for (i = 0; i < 32; i++) {
        poke(0x0806, zelda_square_wave[i]);
    }
    poke(0x0805, 0xFF);

    poke(0x0800, 2);
    poke(0x0804, 0x40);
    poke(0x0804, 0x00);
    for (i = 0; i < 32; i++) {
        poke(0x0806, zelda_triangle_wave[i]);
    }
    poke(0x0805, 0xFF);

    poke(0x0800, 3);
    poke(0x0804, 0x40);
    poke(0x0804, 0x00);
    for (i = 0; i < 32; i++) {
        poke(0x0806, zelda_square_wave[i]);
    }
    poke(0x0805, 0xFF);

    poke(0x0800, 4);
    poke(0x0804, 0x00);
    poke(0x0805, 0xFF);
    poke(0x0807, 0x00);

    music_play(TRACK_TITLE);
}

